S = "Hakeem Force Academy"
QS = [
(S, "How many mountain peaks above 8000 metres are located in Pakistan?", ["3", "4", "5", "7"], 2,
 "Pakistan has five of the world's fourteen eight-thousanders: K2, Nanga Parbat, Gasherbrum I, Broad Peak and Gasherbrum II. The question in the test said feet, but the standard fact is about 8000 metres.",
 "K2 at 8611 metres is the second highest mountain in the world.", [872, 1856]),
(S, "In a class of 1500 students, 1340 are boys. What is the percentage of girls (to two decimal places)?", ["8.67%", "10.67%", "12.50%", "89.33%"], 1,
 "Girls = 1500 - 1340 = 160. Percentage = 160 / 1500 x 100 = 10.67%.",
 "Boys make up 89.33% of this class, and the two percentages add up to 100.", [2055]),
(S, "In which country was FIFA founded in 1904?", ["Switzerland", "Uruguay", "England", "France"], 3,
 "FIFA was founded in Paris, France, on 21 May 1904 by seven European associations.",
 "FIFA headquarters are today in Zurich, Switzerland.", [1759, 489]),
(S, "Which country has won the most FIFA World Cup titles?", ["Germany", "Brazil", "Italy", "Argentina"], 1,
 "Brazil has won the men's World Cup five times (1958, 1962, 1970, 1994, 2002). No other team has more, including after the 2026 tournament.",
 "Spain won the 2026 World Cup, beating Argentina 1-0 after extra time, for their second title.", [3950]),
(S, "Which team was the runner-up in the 2022 FIFA World Cup in Qatar?", ["Croatia", "Morocco", "France", "Brazil"], 2,
 "Argentina beat France on penalties after a 3-3 draw in the 2022 final, so France was the runner-up.",
 "Croatia finished third in 2022 after beating Morocco.", [1381]),
(S, "Which country won the 1978 FIFA World Cup?", ["Netherlands", "Argentina", "Brazil", "West Germany"], 1,
 "Argentina hosted and won the 1978 World Cup, beating the Netherlands 3-1 after extra time in the final.",
 "That was Argentina's first World Cup title; they later won in 1986 and 2022.", [4778]),
(S, "If the 5th day of a month is Sunday, what day will the 24th day of that month be?", ["Wednesday", "Thursday", "Friday", "Saturday"], 2,
 "From the 5th to the 24th is 19 days. 19 divided by 7 leaves remainder 5, and Sunday plus 5 days is Friday.",
 "Dates exactly 7 days apart always fall on the same weekday.", [2009]),
(S, "Against which power did Tipu Sultan of Mysore fight his main wars?", ["The Mughals", "The Marathas only", "The British East India Company", "The Portuguese"], 2,
 "Tipu Sultan fought the Anglo-Mysore wars against the British East India Company and was martyred defending Seringapatam in 1799.",
 "He is known as the Tiger of Mysore.", [812]),
(S, "A jet uses 80 gallons of fuel to fly at 320 km per hour (80 gallons per 320 km). How many gallons are needed to cover 700 km?", ["150", "165", "175", "190"], 2,
 "Fuel per km = 80 / 320 = 0.25 gallons. For 700 km: 700 x 0.25 = 175 gallons.",
 "Fuel needed is directly proportional to distance when the rate of use stays the same.", [889]),
(S, "Which country won the final of the Hockey World Cup played in 2023 (the 2022 edition) in India?", ["Belgium", "Netherlands", "Germany", "Australia"], 2,
 "Germany beat Belgium in a penalty shoot-out after a 3-3 draw in the final in Bhubaneswar, Odisha.",
 "That edition was held in January 2023 and was Germany's third Hockey World Cup title.", [3991]),
(S, "Who was the Finance Minister in the Interim Government of India formed in 1946?", ["Jawaharlal Nehru", "Liaquat Ali Khan", "Sardar Patel", "I. I. Chundrigar"], 1,
 "Liaquat Ali Khan of the Muslim League held the finance portfolio in the 1946 Interim Government.",
 "He presented the famous Poor Man's Budget in 1947.", [920, 4670, 4671]),
(S, "What is the range of the series 3, 6, 10, 15?", ["9", "12", "15", "18"], 1,
 "Range = largest value minus smallest value = 15 - 3 = 12.",
 "The next term of the series is 21 because the gaps grow 3, 4, 5, 6.", [1725]),
(S, "Ring is to finger as watch is to what?", ["Hand", "Wrist", "Time", "Neck"], 1,
 "A ring is worn on the finger and a watch is worn on the wrist.",
 "Analogy questions test the relation of an object to the body part where it is worn.", [2556]),
(S, "Who were the first climbers to reach the summit of K2 in 1954?", ["Edmund Hillary and Tenzing Norgay", "Hermann Buhl and Kurt Diemberger", "Lino Lacedelli and Achille Compagnoni", "Ashraf Aman and Nazir Sabir"], 2,
 "An Italian expedition led by Ardito Desio reached the K2 summit on 31 July 1954 with Lino Lacedelli and Achille Compagnoni.",
 "Ashraf Aman was the first Pakistani to summit K2, in 1977.", [4414]),
(S, "Write the word formed from the numbers 18, 5, 19, 20 (A=1, B=2, and so on).", ["REST", "RUST", "REAT", "PEST"], 0,
 "18 is R, 5 is E, 19 is S and 20 is T, so the word is REST.",
 "In this code Z is 26 and the letters run in order from A=1.", [4864]),
(S, "A jet needs 80 gallons of fuel to fly 360 km. About how many gallons are needed to fly 700 km?", ["140.0", "148.5", "155.6", "162.0"], 2,
 "Fuel per km = 80 / 360 = 0.2222 gallons. For 700 km: 700 x 80 / 360 = 155.6 gallons.",
 "The same ratio method works for any fuel, distance or speed problem.", [1451]),
(S, "Which constitution is currently in force in Pakistan?", ["Constitution of 1956", "Constitution of 1962", "Constitution of 1973", "Constitution of 1985"], 2,
 "Pakistan is governed by the Constitution of 1973, which was adopted in April and enforced on 14 August 1973.",
 "It has been amended many times, including the 18th Amendment in 2010 and the 26th Amendment in 2024.", [1248]),
(S, "Who is the Foreign Minister of India?", ["Rajnath Singh", "S. Jaishankar", "Amit Shah", "Nirmala Sitharaman"], 1,
 "Dr S. Jaishankar is India's Minister of External Affairs and was still in office in October 2026.",
 "He has held the post since 2019.", [4521]),
(S, "Who is the Foreign Minister of Iran?", ["Javad Zarif", "Hossein Amir-Abdollahian", "Abbas Araghchi", "Esmail Baghaei"], 2,
 "Abbas Araghchi has been Iran's Foreign Minister since August 2024 under President Pezeshkian and was still in office in 2026.",
 "Hossein Amir-Abdollahian was the earlier minister and died in a helicopter crash in May 2024.", [4522]),
(S, "Which form of government was provided by the 1956 Constitution of Pakistan?", ["Presidential and unitary", "Parliamentary and federal", "Military and unitary", "Presidential and federal"], 1,
 "The 1956 Constitution made Pakistan an Islamic Republic with a federal, parliamentary system and a single-house legislature.",
 "The 1962 Constitution that followed was presidential.", [2606, 3525]),
(S, "Where was the United Nations founded in 1945?", ["New York", "San Francisco", "Geneva", "London"], 1,
 "The UN Charter was signed in San Francisco on 26 June 1945 at the conference that created the organization.",
 "The UN headquarters are in New York, and the UN officially came into existence on 24 October 1945.", [1235]),
(S, "In which year was the C. R. (Rajagopalachari) Formula put forward?", ["1940", "1942", "1944", "1946"], 2,
 "C. Rajagopalachari proposed the formula in 1944 as a basis for talks between Gandhi and Jinnah.",
 "The Gandhi-Jinnah talks of September 1944 failed, partly because Jinnah rejected the formula.", [2470, 3074, 3607]),
(S, "In which area is Altit Fort located?", ["Skardu", "Chitral", "Hunza", "Swat"], 2,
 "Altit Fort is in Altit village in the Hunza Valley of Gilgit-Baltistan.",
 "It is about 900 years old and is older than the nearby Baltit Fort.", [3717]),
(S, "In which valley is Baltit Fort located?", ["Hunza Valley", "Kalash Valley", "Neelum Valley", "Swat Valley"], 0,
 "Baltit Fort stands above Karimabad in the Hunza Valley of Gilgit-Baltistan.",
 "It is a UNESCO-listed heritage site candidate that was restored with Aga Khan Trust support.", [3722]),
(S, "Near which city is Rawat Fort located?", ["Lahore", "Peshawar", "Rawalpindi", "Multan"], 2,
 "Rawat Fort is a 16th century fort on the Grand Trunk Road about 17 km from Rawalpindi.",
 "It was built by the Gakhars and has many graves of Gakhar chiefs.", [3757]),
(S, "Which famous fort is located in Hyderabad, Sindh?", ["Pacco Qilo", "Rohtas Fort", "Ranikot Fort", "Derawar Fort"], 0,
 "Pacco Qilo (Pucca Fort) stands on Ganjo Takar hill in Hyderabad, Sindh, and was built by the Kalhora ruler Ghulam Shah in 1768.",
 "Ranikot Fort is in Sindh too but near Jamshoro and is called the largest fort in the world by some sources.", [4018]),
(S, "What is the flow of electric charge called?", ["Voltage", "Resistance", "Electric current", "Power"], 2,
 "The flow of electric charge, usually electrons in a wire, is called electric current.",
 "Electric current is measured in amperes.", [3108]),
]
